class SearchPage:
    def __init__(self, page):
        self.page = page
        self.input = page.locator('[aria-label="Enter your search term"]')

    def navigate(self):
        self.page.goto("https://bing.com")

    def search(self, text):
        self.input.fill(text)
        self.input.press("Enter")
